DROP TABLE IF EXISTS `forecast_adjustments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `forecast_adjustments` (
  `forecast_adjustment_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `forecast_product_day_id` int(11) NOT NULL,
  `adjusted_quantity` decimal(12,2) NOT NULL,
  `reason` varchar(100) NOT NULL,
  `adjusted_by` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`forecast_adjustment_id`),
  UNIQUE KEY `forecast_product_day_id` (`forecast_product_day_id`),
  KEY `fk_forecast_adjustment_user` (`adjusted_by`),
  CONSTRAINT `fk_forecast_adjustment_day` FOREIGN KEY (`forecast_product_day_id`) REFERENCES `forecast_product_days` (`forecast_product_day_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_forecast_adjustment_user` FOREIGN KEY (`adjusted_by`) REFERENCES `users` (`user_id`),
  CONSTRAINT `nonnegative_adjusted_quantity` CHECK (`adjusted_quantity` >= 0)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

