--
-- Table structure for table `forecast_product_days`
--

DROP TABLE IF EXISTS `forecast_product_days`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `forecast_product_days` (
  `forecast_product_day_id` int(11) NOT NULL AUTO_INCREMENT,
  `forecast_run_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `forecast_date` date NOT NULL,
  `method_used` enum('Not enough history','Day-of-week average','Random Forest') NOT NULL,
  `sales_history_days` int(11) NOT NULL,
  `predicted_quantity` decimal(12,2) NOT NULL,
  `available_stock` int(11) NOT NULL,
  `recommended_to_prepare` decimal(12,2) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`forecast_product_day_id`),
  UNIQUE KEY `unique_forecast_product_day` (`forecast_run_id`,`product_id`,`forecast_date`),
  KEY `idx_forecast_product_days_product_date` (`product_id`,`forecast_date`),
  CONSTRAINT `fk_forecast_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`),
  CONSTRAINT `fk_forecast_product_run` FOREIGN KEY (`forecast_run_id`) REFERENCES `forecast_runs` (`forecast_run_id`) ON DELETE CASCADE,
  CONSTRAINT `valid_history_days` CHECK (`sales_history_days` >= 0),
  CONSTRAINT `valid_predicted_quantity` CHECK (`predicted_quantity` >= 0),
  CONSTRAINT `valid_available_stock` CHECK (`available_stock` >= 0),
  CONSTRAINT `valid_recommended_quantity` CHECK (`recommended_to_prepare` >= 0)
) ENGINE=InnoDB AUTO_INCREMENT=3407 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

